package com.mfg.qms.controller;
import com.mfg.common.api.*;import com.mfg.common.exception.BizException;import com.mfg.qms.entity.Inspection;import com.mfg.qms.repo.InspectionRepository;import com.mfg.qms.service.QmsLifecycleService;import com.mfg.security.config.CurrentUser;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;
@RestController @RequestMapping("/api/qms/inspections") @RequiredArgsConstructor public class InspectionController{private final InspectionRepository repo;private final QmsLifecycleService flow;@GetMapping public ApiResponse<Page<Inspection>>page(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(repo.findAll(PageRequest.of(Math.max(0,page-1),Math.min(size,200))));}@GetMapping("/{id}")public ApiResponse<Inspection>detail(@PathVariable Long id){return ApiResponse.ok(repo.findById(id).orElseThrow(()->BizException.notFound("检验单",id)));}@PostMapping public ApiResponse<Inspection>create(@RequestBody Inspection i){if(repo.existsByInspectionNo(i.getInspectionNo()))throw BizException.of(ErrorCode.MASTER_DATA_ALREADY_EXISTS,"检验单号已存在");i.setResult("PENDING");i.setInspectDate(LocalDate.now());i.setInspectorCode(CurrentUser.usernameOrSystem());return ApiResponse.ok(repo.save(i));}@PostMapping("/{id}/judge")public ApiResponse<?>judge(@PathVariable Long id,@RequestParam BigDecimal qualifiedQty,@RequestParam BigDecimal defectQty,@RequestParam String result){return ApiResponse.ok(flow.judge(id,qualifiedQty,defectQty,result));}}
